import "dart:convert";
import "dart:typed_data";

/// Transparent high-fidelity Gyan educator mascot states for OTP verification.
/// - [openEyesBytes]: Welcoming stance with open eyes.
/// - [hidingEyesBytes]: Privacy-guarding stance covering both eyes with wings/hands.
/// - [peekingEyesBytes]: Cheerful wink/peek when OTP code is complete or during verification.
class OtpMascotData {
  static const String openEyesBase64 = "";
  static const String hidingEyesBase64 = "";
  static const String peekingEyesBase64 = "";

  static Uint8List? _openEyesBytes;
  static Uint8List get openEyesBytes =>
      _openEyesBytes ??= base64Decode(openEyesBase64);

  static Uint8List? _hidingEyesBytes;
  static Uint8List get hidingEyesBytes =>
      _hidingEyesBytes ??= base64Decode(hidingEyesBase64);

  static Uint8List? _peekingEyesBytes;
  static Uint8List get peekingEyesBytes =>
      _peekingEyesBytes ??= base64Decode(peekingEyesBase64);
}
